use rand::Rng;
use std::io::{stdout, Write};
use std::time::{Duration, Instant};

const BOARD_WIDTH: usize = 10;
const BOARD_HEIGHT: usize = 20;
const BLOCK_SIZE: usize = 2;

#[derive(Clone, Copy, PartialEq)]
enum ColorType {
    Cyan,
    Yellow,
    Purple,
    Green,
    Red,
    Blue,
    Orange,
}

#[derive(Clone, Copy)]
struct Piece {
    shape: [[bool; 4]; 4],
    color: ColorType,
    x: usize,
    y: usize,
}

impl Piece {
    fn new(shape: [[bool; 4]; 4], color: ColorType) -> Self {
        Piece {
            shape,
            color,
            x: BOARD_WIDTH / 2 - 2,
            y: 0,
        }
    }

    fn rotate(&self) -> Piece {
        let mut new_shape = [[false; 4]; 4];
        for i in 0..4 {
            for j in 0..4 {
                new_shape[j][3 - i] = self.shape[i][j];
            }
        }
        Piece {
            shape: new_shape,
            color: self.color,
            x: self.x,
            y: self.y,
        }
    }
}

struct Game {
    board: [[Option<ColorType>; BOARD_HEIGHT]; BOARD_WIDTH],
    current_piece: Piece,
    next_piece: Piece,
    score: u32,
    level: u32,
    lines: u32,
    game_over: bool,
}

impl Game {
    fn new() -> Self {
        let mut rng = rand::thread_rng();
        let piece_type = rng.gen_range(0..7);

        Game {
            board: [[None; BOARD_HEIGHT]; BOARD_WIDTH],
            current_piece: Self::create_piece(piece_type),
            next_piece: Self::create_piece(rng.gen_range(0..7)),
            score: 0,
            level: 1,
            lines: 0,
            game_over: false,
        }
    }

    fn create_piece(piece_type: usize) -> Piece {
        match piece_type {
            0 => Piece::new(
                [
                    [false, false, false, false],
                    [true, true, true, true],
                    [false, false, false, false],
                    [false, false, false, false],
                ],
                ColorType::Cyan,
            ), // I
            1 => Piece::new(
                [
                    [false, false, false, false],
                    [true, true, true, false],
                    [false, true, false, false],
                    [false, false, false, false],
                ],
                ColorType::Yellow,
            ), // T
            2 => Piece::new(
                [
                    [false, false, false, false],
                    [true, true, true, false],
                    [false, false, true, false],
                    [false, false, false, false],
                ],
                ColorType::Purple,
            ), // L
            3 => Piece::new(
                [
                    [false, false, false, false],
                    [true, true, true, false],
                    [true, false, false, false],
                    [false, false, false, false],
                ],
                ColorType::Blue,
            ), // J
            4 => Piece::new(
                [
                    [false, false, false, false],
                    [false, true, true, false],
                    [true, true, false, false],
                    [false, false, false, false],
                ],
                ColorType::Green,
            ), // S
            5 => Piece::new(
                [
                    [false, false, false, false],
                    [true, true, false, false],
                    [false, true, true, false],
                    [false, false, false, false],
                ],
                ColorType::Red,
            ), // Z
            6 => Piece::new(
                [
                    [false, false, false, false],
                    [false, true, false, false],
                    [true, true, true, false],
                    [false, false, false, false],
                ],
                ColorType::Orange,
            ), // O
            _ => unreachable!(),
        }
    }

    fn color_for_type(color: ColorType) -> Color {
        match color {
            ColorType::Cyan => Color::Cyan,
            ColorType::Yellow => Color::Yellow,
            ColorType::Purple => Color::Magenta,
            ColorType::Green => Color::Green,
            ColorType::Red => Color::Red,
            ColorType::Blue => Color::Blue,
            ColorType::Orange => Color::DarkGrey,
        }
    }

    fn valid_move(&self, piece: &Piece, dx: i32, dy: i32) -> bool {
        let new_x = piece.x as i32 + dx;
        let new_y = piece.y as i32 + dy;

        for i in 0..4 {
            for j in 0..4 {
                if piece.shape[i][j] {
                    let board_x = new_x + j as i32;
                    let board_y = new_y + i as i32;

                    if board_x < 0 || board_x >= BOARD_WIDTH as i32 {
                        return false;
                    }
                    if board_y >= BOARD_HEIGHT as i32 {
                        return false;
                    }
                    if board_y >= 0 && self.board[board_x as usize][board_y as usize].is_some() {
                        return false;
                    }
                }
            }
        }
        true
    }

    fn move_piece(&mut self, dx: i32, dy: i32) {
        if self.valid_move(&self.current_piece, dx, dy) {
            self.current_piece.x = (self.current_piece.x as i32 + dx) as usize;
            self.current_piece.y = (self.current_piece.y as i32 + dy) as usize;
        }
    }

    fn rotate_piece(&mut self) {
        let rotated = self.current_piece.rotate();
        if self.valid_move(&rotated, 0, 0) {
            self.current_piece = rotated;
        }
    }

    fn lock_piece(&mut self) {
        for i in 0..4 {
            for j in 0..4 {
                if self.current_piece.shape[i][j] {
                    let x = self.current_piece.x + j;
                    let y = self.current_piece.y + i;
                    if y < BOARD_HEIGHT {
                        self.board[x][y] = Some(self.current_piece.color);
                    }
                }
            }
        }
        self.clear_lines();
        self.current_piece = self.next_piece;
        self.next_piece = Self::create_piece(rand::thread_rng().gen_range(0..7));

        if !self.valid_move(&self.current_piece, 0, 0) {
            self.game_over = true;
        }
    }

    fn clear_lines(&mut self) {
        let mut lines_cleared = 0;
        let mut y = BOARD_HEIGHT - 1;

        while y > 0 {
            if self.board.iter().all(|col| col[y].is_some()) {
                lines_cleared += 1;
                for yy in (1..=y).rev() {
                    for x in 0..BOARD_WIDTH {
                        self.board[x][yy] = self.board[x][yy - 1];
                    }
                }
                for x in 0..BOARD_WIDTH {
                    self.board[x][0] = None;
                }
            } else {
                y -= 1;
            }
        }

        if lines_cleared > 0 {
            self.lines += lines_cleared;
            self.score += match lines_cleared {
                1 => 100 * self.level,
                2 => 300 * self.level,
                3 => 500 * self.level,
                4 => 800 * self.level,
                _ => 0,
            };
            self.level = self.lines / 10 + 1;
        }
    }

    fn drop(&mut self) {
        if self.valid_move(&self.current_piece, 0, 1) {
            self.current_piece.y += 1;
        } else {
            self.lock_piece();
        }
    }

    fn hard_drop(&mut self) {
        while self.valid_move(&self.current_piece, 0, 1) {
            self.current_piece.y += 1;
            self.score += 2;
        }
        self.lock_piece();
    }
}

fn draw_block(x: usize, y: usize, color: Color) -> String {
    format!(
        "\x1b[{};{}H\x1b[48;5;{}m  \x1b[0m",
        y + 1,
        x * 2 + 1,
        match color {
            Color::Cyan => 51,
            Color::Yellow => 226,
            Color::Magenta => 129,
            Color::Green => 46,
            Color::Red => 196,
            Color::Blue => 21,
            Color::DarkGrey => 242,
            _ => 15,
        }
    )
}

fn draw_board(game: &Game) -> String {
    let mut output = String::new();

    // Draw border
    for y in 0..BOARD_HEIGHT {
        output.push_str(&format!("\x1b[{};{}H│", y + 1, 1));
        output.push_str(&format!("\x1b[{};{}H│", y + 1, BOARD_WIDTH * 2 + 2));
    }
    output.push_str(&format!("\x1b[{};{}H┌", BOARD_HEIGHT + 1, 1));
    output.push_str(&format!(
        "\x1b[{};{}H┐",
        BOARD_HEIGHT + 1,
        BOARD_WIDTH * 2 + 2
    ));
    output.push_str(&format!(
        "\x1b[{};{}H└",
        BOARD_HEIGHT + 2,
        1
    ));
    output.push_str(&format!(
        "\x1b[{};{}H┘",
        BOARD_HEIGHT + 2,
        BOARD_WIDTH * 2 + 2
    ));

    // Draw top and bottom borders
    for x in 0..BOARD_WIDTH {
        output.push_str(&format!(
            "\x1b[{};{}H─",
            BOARD_HEIGHT + 1,
            x * 2 + 2
        ));
        output.push_str(&format!(
            "\x1b[{};{}H─",
            BOARD_HEIGHT + 2,
            x * 2 + 2
        ));
    }

    // Draw board content
    for x in 0..BOARD_WIDTH {
        for y in 0..BOARD_HEIGHT {
            if let Some(color) = game.board[x][y] {
                output.push_str(&draw_block(x, y, Game::color_for_type(color)));
            }
        }
    }

    // Draw current piece
    for i in 0..4 {
        for j in 0..4 {
            if game.current_piece.shape[i][j] {
                let x = game.current_piece.x + j;
                let y = game.current_piece.y + i;
                if y < BOARD_HEIGHT {
                    output.push_str(&draw_block(
                        x,
                        y,
                        Game::color_for_type(game.current_piece.color),
                    ));
                }
            }
        }
    }

    output
}

fn draw_ui(game: &Game) -> String {
    let mut output = String::new();

    // Draw next piece preview
    output.push_str(&format!("\x1b[{};{}HNext:", 3, BOARD_WIDTH * 2 + 4));
    for i in 0..4 {
        for j in 0..4 {
            if game.next_piece.shape[i][j] {
                let x = BOARD_WIDTH * 2 + 4 + j;
                let y = 4 + i;
                output.push_str(&draw_block(
                    BOARD_WIDTH + 2 + j,
                    3 + i,
                    Game::color_for_type(game.next_piece.color),
                ));
            }
        }
    }

    // Draw score
    output.push_str(&format!(
        "\x1b[{};{}HScore: {}",
        8,
        BOARD_WIDTH * 2 + 4,
        game.score
    ));

    // Draw level
    output.push_str(&format!(
        "\x1b[{};{}HLevel: {}",
        10,
        BOARD_WIDTH * 2 + 4,
        game.level
    ));

    // Draw lines
    output.push_str(&format!(
        "\x1b[{};{}HLines: {}",
        12,
        BOARD_WIDTH * 2 + 4,
        game.lines
    ));

    // Draw controls
    output.push_str(&format!("\x1b[{};{}HControls:", 15, BOARD_WIDTH * 2 + 4));
    output.push_str(&format!("\x1b[{};{}H← → Move", 16, BOARD_WIDTH * 2 + 4));
    output.push_str(&format!("\x1b[{};{}H↑ Rotate", 17, BOARD_WIDTH * 2 + 4));
    output.push_str(&format!("\x1b[{};{}H↓ Soft drop", 18, BOARD_WIDTH * 2 + 4));
    output.push_str(&format!("\x1b[{};{}HSpace Hard drop", 19, BOARD_WIDTH * 2 + 4));
    output.push_str(&format!("\x1b[{};{}HQ Quit", 20, BOARD_WIDTH * 2 + 4));

    if game.game_over {
        output.push_str(&format!(
            "\x1b[{};{}HGAME OVER!",
            BOARD_HEIGHT / 2,
            BOARD_WIDTH / 2
        ));
        output.push_str(&format!(
            "\x1b[{};{}HPress R to restart",
            BOARD_HEIGHT / 2 + 2,
            BOARD_WIDTH / 2 - 2
        ));
    }

    output
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut stdout = stdout();

    terminal::enable_raw_mode()?;
    execute!(stdout, EnterAlternateScreen, Hide)?;
    stdout.flush()?;

    let mut game = Game::new();
    let mut last_drop = Instant::now();
    let drop_interval = Duration::from_millis(1000 / game.level as u64);

    loop {
        // Clear screen
        execute!(stdout, Clear(ClearType::All))?;

        // Draw game
        let board = draw_board(&game);
        let ui = draw_ui(&game);
        execute!(stdout, Print(board), Print(ui))?;
        stdout.flush()?;

        // Handle timing
        let drop_speed = Duration::from_millis(1000 / game.level as u64);
        if last_drop.elapsed() > drop_speed {
            game.drop();
            last_drop = Instant::now();
        }

        // Handle input
        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                match code {
                    KeyCode::Left => game.move_piece(-1, 0),
                    KeyCode::Right => game.move_piece(1, 0),
                    KeyCode::Down => game.move_piece(0, 1),
                    KeyCode::Up => game.rotate_piece(),
                    KeyCode::Char(' ') => game.hard_drop(),
                    KeyCode::Char('q') | KeyCode::Esc => break,
                    KeyCode::Char('r') if game.game_over => {
                        game = Game::new();
                        last_drop = Instant::now();
                    }
                    _ => {}
                }
            }
        }
    }

    terminal::disable_raw_mode()?;
    execute!(stdout, Show, LeaveAlternateScreen)?;

    println!("Thanks for playing! Final Score: {}", game.score);

    Ok(())
}
"}

